const item = $input.first().json;

let text = item.text ?? item.data ?? '';
if (typeof text !== 'string') text = String(text || '');
text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();

if (!text) {
  throw new Error('The uploaded file appears to be empty or could not be read. If it is a scanned PDF, the text cannot be extracted. Export a CSV from your bank instead.');
}

const currencySymbol = (text.match(/[₹$£€]/) || [''])[0];

// ---------- helpers ----------
const detectDelimiter = (sampleLines) => {
  const cands = [',', ';', '\t', '|'];
  let best = ',', bestScore = -1;
  cands.forEach(d => {
    const counts = sampleLines.map(l => l.split(d).length - 1).filter(c => c > 0);
    if (counts.length < 2) return;
    // prefer the delimiter that appears consistently on most lines
    const avg = counts.reduce((a, b) => a + b, 0) / counts.length;
    const score = counts.length * avg;
    if (score > bestScore) { bestScore = score; best = d; }
  });
  return best;
};

const parseCsvLine = (line, delim) => {
  const out = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQ && line[i + 1] === '"') { cur += '"'; i++; }
      else inQ = !inQ;
    } else if (ch === delim && !inQ) {
      out.push(cur.trim()); cur = '';
    } else cur += ch;
  }
  out.push(cur.trim());
  return out;
};

const toNumber = (raw) => {
  if (raw === null || raw === undefined) return null;
  let s = String(raw).trim();
  if (!s) return null;

  let neg = false;
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
  if (/(^|\s)(dr|debit)\b/i.test(s)) neg = true;
  if (/(^|\s)(cr|credit)\b/i.test(s)) neg = false;
  if (s.trim().startsWith('-')) neg = true;

  s = s.replace(/[₹$£€]/g, '').replace(/\b(dr|cr|debit|credit|inr|usd|gbp|eur)\b/gi, '').trim();
  s = s.replace(/[+\-]/g, '').trim();

  // 1.234,56 (european) vs 1,234.56
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');

  s = s.replace(/[^0-9.]/g, '');
  if (!s || s === '.') return null;

  const n = parseFloat(s);
  if (!isFinite(n)) return null;
  return neg ? -Math.abs(n) : Math.abs(n);
};

const parseDate = (raw, order) => {
  if (!raw) return null;
  const s = String(raw).trim();

  let m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (m) return { y: +m[1], mo: +m[2], d: +m[3] };

  m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})/);
  if (m) {
    let a = +m[1], b = +m[2], y = +m[3];
    if (y < 100) y += 2000;
    let d, mo;
    if (a > 12) { d = a; mo = b; }
    else if (b > 12) { d = b; mo = a; }
    else if (order === 'mdy') { mo = a; d = b; }
    else { d = a; mo = b; }
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
    return { y, mo, d };
  }

  const months = { jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12 };
  m = s.match(/^(\d{1,2})[-\s]([a-z]{3})[a-z]*[-\s](\d{2,4})/i);
  if (m) {
    let y = +m[3]; if (y < 100) y += 2000;
    return { y, mo: months[m[2].toLowerCase()], d: +m[1] };
  }
  m = s.match(/^([a-z]{3})[a-z]*\s+(\d{1,2}),?\s+(\d{4})/i);
  if (m) return { y: +m[3], mo: months[m[1].toLowerCase()], d: +m[2] };

  return null;
};

// Work out whether the file uses DD/MM or MM/DD, once, for the whole file.
// Statements are normally in date order, so we pick the reading that produces
// the most chronological sequence, and fall back to hard evidence if present.
const detectDateOrder = (rawDates) => {
  const pairs = [];
  rawDates.forEach(s => {
    const m = String(s).trim().match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})/);
    if (m) pairs.push([+m[1], +m[2], +m[3] < 100 ? +m[3] + 2000 : +m[3]]);
  });
  if (!pairs.length) return 'dmy';

  if (pairs.some(p => p[0] > 12)) return 'dmy';
  if (pairs.some(p => p[1] > 12)) return 'mdy';

  const score = (order) => {
    let ok = 0, prev = null;
    pairs.forEach(p => {
      const mo = order === 'mdy' ? p[0] : p[1];
      const d = order === 'mdy' ? p[1] : p[0];
      const v = p[2] * 10000 + mo * 100 + d;
      if (prev !== null && v >= prev) ok++;
      prev = v;
    });
    return ok;
  };
  return score('mdy') > score('dmy') ? 'mdy' : 'dmy';
};

const fmtDate = (o) => o
  ? o.y + '-' + String(o.mo).padStart(2, '0') + '-' + String(o.d).padStart(2, '0')
  : '';

const cleanDesc = (s) => String(s || '')
  .replace(/\s+/g, ' ')
  .replace(/^["']|["']$/g, '')
  .trim();

// ---------- CSV path ----------
const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const delim = detectDelimiter(lines.slice(0, 20));
const delimCount = (l) => (l.split(delim).length - 1);
const looksCsv = lines.length > 2 && lines.slice(0, 15).filter(l => delimCount(l) >= 2).length >= 3;

let transactions = [];
let parseMode = '';
let dateOrder = 'dmy';

if (looksCsv) {
  parseMode = 'csv';

  const AMT_HEADER = /amount|amt|debit|credit|withdraw|deposit|paid\s*out|paid\s*in|money\s*out|money\s*in|betrag|value|dr|cr/;
  const DATE_HEADER = /date|datum|posted|txn|fecha/;

  // find the header row: the first row whose cells include a date-ish and amount-ish word
  let headerIdx = -1, header = [];
  for (let i = 0; i < Math.min(lines.length, 25); i++) {
    const cells = parseCsvLine(lines[i], delim).map(c => c.toLowerCase());
    if (cells.some(c => DATE_HEADER.test(c)) && cells.some(c => AMT_HEADER.test(c))) {
      headerIdx = i; header = cells; break;
    }
  }

  const findCol = (patterns, exclude) => {
    for (const p of patterns) {
      for (let i = 0; i < header.length; i++) {
        if (exclude && exclude.test(header[i])) continue;
        if (p.test(header[i])) return i;
      }
    }
    return -1;
  };

  let iDate = -1, iDesc = -1, iAmt = -1, iDebit = -1, iCredit = -1, iType = -1;

  if (headerIdx >= 0) {
    iDate = findCol([/^date$/, /txn.*date/, /transaction date/, /value date/, /posted/, /datum/, /date/]);
    iDesc = findCol([/description/, /particular/, /narration/, /details/, /merchant/, /payee/, /remark/, /memo/, /beschreibung/, /reference/]);
    iDebit = findCol([/^debit$/, /debit amount/, /withdraw/, /paid\s*out/, /money\s*out/, /debit/], /indicator|type|balance/);
    iCredit = findCol([/^credit$/, /credit amount/, /deposit/, /paid\s*in/, /money\s*in/, /credit/], /indicator|type|balance/);
    iAmt = findCol([/^amount$/, /^amt$/, /^betrag$/, /transaction amount/, /amount/], /balance/);
    iType = findCol([/^type$/, /dr.*cr/, /cr.*dr/, /indicator/]);
  }

  const dataStart = headerIdx >= 0 ? headerIdx + 1 : 0;

  // decide DD/MM vs MM/DD once for the whole file
  const rawDateSamples = [];
  for (let i = dataStart; i < lines.length; i++) {
    const cells = parseCsvLine(lines[i], delim);
    if (iDate >= 0 && cells[iDate]) rawDateSamples.push(cells[iDate]);
    else cells.forEach(c => { if (/^\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}/.test(String(c).trim())) rawDateSamples.push(c); });
  }
  dateOrder = detectDateOrder(rawDateSamples);

  for (let i = dataStart; i < lines.length; i++) {
    const cells = parseCsvLine(lines[i], delim);
    if (cells.length < 2) continue;

    let dateObj = null, desc = '', amount = null;

    if (headerIdx >= 0) {
      dateObj = parseDate(cells[iDate], dateOrder);
      desc = cleanDesc(cells[iDesc]);

      if (iDebit >= 0 || iCredit >= 0) {
        const dv = iDebit >= 0 ? toNumber(cells[iDebit]) : null;
        const cv = iCredit >= 0 ? toNumber(cells[iCredit]) : null;
        if (dv !== null && Math.abs(dv) > 0) amount = -Math.abs(dv);
        else if (cv !== null && Math.abs(cv) > 0) amount = Math.abs(cv);
      }
      if (amount === null && iAmt >= 0) {
        amount = toNumber(cells[iAmt]);
        if (amount !== null && iType >= 0) {
          const t = String(cells[iType] || '').toLowerCase();
          if (/^dr|debit|withdraw/.test(t)) amount = -Math.abs(amount);
          else if (/^cr|credit|deposit/.test(t)) amount = Math.abs(amount);
        }
      }
    }

    // fallback: scan the row positionally
    if (!dateObj || amount === null) {
      for (let c = 0; c < cells.length && !dateObj; c++) dateObj = parseDate(cells[c], dateOrder);
      if (amount === null) {
        const nums = [];
        cells.forEach((c, idx) => {
          const n = toNumber(c);
          if (n !== null && /\d/.test(c)) nums.push({ n, idx });
        });
        if (nums.length) amount = nums[nums.length > 1 ? nums.length - 2 : 0].n;
      }
      if (!desc) {
        const textCells = cells.filter(c => c && !parseDate(c, dateOrder) && toNumber(c) === null);
        desc = cleanDesc(textCells.sort((a, b) => b.length - a.length)[0] || '');
      }
    }

    if (!dateObj || amount === null || amount === 0) continue;
    if (!desc) desc = 'Unlabelled transaction';

    transactions.push({ date: fmtDate(dateObj), y: dateObj.y, mo: dateObj.mo, d: dateObj.d, description: desc, amount });
  }
}

// ---------- PDF / plain text path ----------
if (!transactions.length) {
  parseMode = 'text';
  const preDateRe = /(\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4})/;
  const textDateSamples = [];
  text.split('\n').forEach(l => { const m = l.match(preDateRe); if (m) textDateSamples.push(m[1]); });
  dateOrder = detectDateOrder(textDateSamples);

  const dateRe = /(\d{1,2}[-/.][A-Za-z]{3,}[-/.]\d{2,4}|\d{4}-\d{2}-\d{2}|\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}|[A-Za-z]{3,}\s+\d{1,2},?\s+\d{4})/;
  const amtRe = /(\(?-?[₹$£€]?\s?\d[\d,]*\.?\d{0,2}\)?\s?(?:dr|cr)?)\s*$/i;

  text.split('\n').forEach(line => {
    const l = line.trim();
    if (!l || l.length < 8) return;
    const dm = l.match(dateRe);
    if (!dm) return;
    const dateObj = parseDate(dm[1], dateOrder);
    if (!dateObj) return;

    const rest = l.slice(dm.index + dm[1].length).trim();
    const allNums = rest.match(/\(?-?[₹$£€]?\s?\d[\d,]*\.?\d{0,2}\)?\s?(?:dr|cr)?/gi) || [];
    if (!allNums.length) return;

    // last number on a statement line is usually the running balance
    const amtRaw = allNums.length > 1 ? allNums[allNums.length - 2] : allNums[0];
    let amount = toNumber(amtRaw);
    if (amount === null || amount === 0) return;

    if (/\bcr\b|credit|deposit/i.test(rest) && amount < 0) amount = Math.abs(amount);
    else if (/\bdr\b|debit|withdraw/i.test(rest)) amount = -Math.abs(amount);
    else if (amount > 0 && allNums.length > 1) amount = -amount; // most statement rows are spends

    let desc = rest;
    allNums.forEach(n => { desc = desc.replace(n, ' '); });
    desc = cleanDesc(desc);
    if (!desc || desc.length < 2) desc = 'Unlabelled transaction';

    transactions.push({ date: fmtDate(dateObj), y: dateObj.y, mo: dateObj.mo, d: dateObj.d, description: desc, amount });
  });
}

if (!transactions.length) {
  throw new Error('Could not read any transactions from this file. Supported: a CSV exported from your bank, or a text based PDF statement. Scanned or image PDFs will not work. Check that the file has a date column and an amount column.');
}

// ---------- normalize merchant names ----------
const normalize = (d) => {
  let s = ' ' + d.toLowerCase() + ' ';
  s = s.replace(/\b(upi|neft|imps|rtgs|ach|pos|atm|ecs|nach|vps|ref|txn|trf|tfr|pmt|payment to|paid to|purchase at|card ending|xx+\d*)\b/g, ' ');
  s = s.replace(/\b\d{4,}\b/g, ' ');
  s = s.replace(/[^a-z\s&.]/g, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  const words = s.split(' ').filter(w => w.length > 1).slice(0, 4);
  return words.join(' ') || d.toLowerCase().slice(0, 30);
};

transactions.forEach(t => { t.merchant = normalize(t.description); });

// unique merchants only, so the LLM classifies a small list instead of every row
const uniqueMap = {};
transactions.forEach(t => {
  if (!uniqueMap[t.merchant]) uniqueMap[t.merchant] = { merchant: t.merchant, sample: t.description, count: 0 };
  uniqueMap[t.merchant].count++;
});
const uniqueMerchants = Object.values(uniqueMap).sort((a, b) => b.count - a.count);

const spendTotal = transactions.filter(t => t.amount < 0).reduce((s, t) => s + Math.abs(t.amount), 0);
const incomeTotal = transactions.filter(t => t.amount > 0).reduce((s, t) => s + t.amount, 0);

const dates = transactions.map(t => t.date).filter(Boolean).sort();

return [{
  json: {
    parse_mode: parseMode,
    date_order: dateOrder === 'mdy' ? 'month/day/year' : 'day/month/year',
    currency: currencySymbol,
    transaction_count: transactions.length,
    unique_merchant_count: uniqueMerchants.length,
    period_start: dates[0] || '',
    period_end: dates[dates.length - 1] || '',
    spend_total: Number(spendTotal.toFixed(2)),
    income_total: Number(incomeTotal.toFixed(2)),
    transactions,
    unique_merchants: uniqueMerchants
  }
}];

const res = $input.first().json;

let raw = res.output ?? res.text ?? res.content ?? '';
if (typeof raw === 'object' && raw !== null) raw = JSON.stringify(raw);
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }

const d = $('Build Category Prompt').first().json.payload;

// map merchant -> {category, clean_name}
const map = {};
if (parsed && Array.isArray(parsed.categories)) {
  parsed.categories.forEach(c => {
    if (c && c.merchant) {
      map[String(c.merchant).toLowerCase()] = {
        category: c.category || 'Other',
        clean_name: c.clean_name || c.merchant
      };
    }
  });
}

const titleCase = (s) => String(s).replace(/\b\w/g, ch => ch.toUpperCase());

let uncategorized = 0;
const txns = d.transactions.map(t => {
  const hit = map[t.merchant.toLowerCase()];
  if (!hit) uncategorized++;
  let category = hit ? hit.category : (t.amount > 0 ? 'Income' : 'Other');
  // trust the sign over the label: money in cannot be an expense category
  if (t.amount > 0 && category !== 'Income' && category !== 'Transfers') category = 'Income';
  if (t.amount < 0 && category === 'Income') category = 'Other';
  return {
    date: t.date,
    y: t.y,
    mo: t.mo,
    d: t.d,
    description: t.description,
    merchant: t.merchant,
    clean_name: hit ? hit.clean_name : titleCase(t.merchant),
    category,
    amount: t.amount
  };
});

const round = (n) => Number(n.toFixed(2));

// ---------- category totals (spend only) ----------
const catMap = {};
txns.filter(t => t.amount < 0).forEach(t => {
  if (!catMap[t.category]) catMap[t.category] = { category: t.category, total: 0, count: 0, merchants: {} };
  const c = catMap[t.category];
  const amt = Math.abs(t.amount);
  c.total += amt;
  c.count++;
  if (!c.merchants[t.clean_name]) c.merchants[t.clean_name] = 0;
  c.merchants[t.clean_name] += amt;
});

const spendTotal = Object.values(catMap).reduce((s, c) => s + c.total, 0);

const categories = Object.values(catMap).map(c => ({
  category: c.category,
  total: round(c.total),
  count: c.count,
  pct: spendTotal ? round((c.total / spendTotal) * 100) : 0,
  top_merchants: Object.keys(c.merchants)
    .map(k => ({ name: k, total: round(c.merchants[k]) }))
    .sort((a, b) => b.total - a.total)
    .slice(0, 4)
})).sort((a, b) => b.total - a.total);

// ---------- monthly totals ----------
const monthMap = {};
txns.forEach(t => {
  const key = t.y + '-' + String(t.mo).padStart(2, '0');
  if (!monthMap[key]) monthMap[key] = { month: key, spend: 0, income: 0, count: 0 };
  if (t.amount < 0) monthMap[key].spend += Math.abs(t.amount);
  else monthMap[key].income += t.amount;
  monthMap[key].count++;
});
const months = Object.values(monthMap)
  .map(m => ({ month: m.month, spend: round(m.spend), income: round(m.income), net: round(m.income - m.spend), count: m.count }))
  .sort((a, b) => a.month.localeCompare(b.month));

// ---------- recurring detection (measured, not guessed) ----------
const byMerchant = {};
txns.filter(t => t.amount < 0).forEach(t => {
  if (!byMerchant[t.merchant]) byMerchant[t.merchant] = [];
  byMerchant[t.merchant].push(t);
});

const recurring = [];
// categories where spend naturally varies, so a stable-looking run is coincidence
const VARIABLE_CATS = /^(Groceries|Dining & Takeaway|Fuel|Shopping|Transport|Cash Withdrawal|Transfers|Travel|Health & Medical|Other)$/;

Object.keys(byMerchant).forEach(m => {
  const list = byMerchant[m];
  const distinctMonths = Array.from(new Set(list.map(t => t.y + '-' + String(t.mo).padStart(2, '0')))).sort();
  if (distinctMonths.length < 2) return;

  // roughly one charge per month, not a merchant visited many times
  if (list.length > distinctMonths.length * 1.5) return;

  const cat = list[0].category;
  const amounts = list.map(t => Math.abs(t.amount));
  const avg = amounts.reduce((a, b) => a + b, 0) / amounts.length;
  if (avg <= 0) return;

  const maxDev = Math.max.apply(null, amounts.map(a => Math.abs(a - avg)));
  const variance = maxDev / avg;

  // a real subscription bills a near identical amount each time
  const tolerance = VARIABLE_CATS.test(cat) ? 0.02 : 0.1;
  if (variance > tolerance) return;

  // charged on a similar day of the month
  const days = list.map(t => t.d || Number(String(t.date).slice(8, 10))).filter(n => n > 0);
  if (days.length >= 2) {
    const avgDay = days.reduce((a, b) => a + b, 0) / days.length;
    const dayDev = Math.max.apply(null, days.map(x => Math.min(Math.abs(x - avgDay), 31 - Math.abs(x - avgDay))));
    if (dayDev > 7) return;
  }

  recurring.push({
    name: list[0].clean_name,
    category: cat,
    typical_amount: round(avg),
    charges: list.length,
    months_seen: distinctMonths.length,
    first_seen: distinctMonths[0],
    last_seen: distinctMonths[distinctMonths.length - 1],
    total_paid: round(amounts.reduce((a, b) => a + b, 0)),
    annualized: round(avg * 12)
  });
});
recurring.sort((a, b) => b.annualized - a.annualized);

const lastMonth = months.length ? months[months.length - 1].month : '';
const dormant = recurring.filter(r => lastMonth && r.last_seen !== lastMonth);

// ---------- top single transactions ----------
const biggest = txns.filter(t => t.amount < 0)
  .sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount))
  .slice(0, 10)
  .map(t => ({ date: t.date, name: t.clean_name, description: t.description, category: t.category, amount: round(Math.abs(t.amount)) }));

const incomeTotal = txns.filter(t => t.amount > 0).reduce((s, t) => s + t.amount, 0);
const monthCount = months.length || 1;

return [{
  json: {
    currency: d.currency,
    parse_mode: d.parse_mode,
    llm_ok: !!parsed,
    uncategorized_count: uncategorized,
    period_start: d.period_start,
    period_end: d.period_end,
    transaction_count: txns.length,
    month_count: monthCount,
    spend_total: round(spendTotal),
    income_total: round(incomeTotal),
    net_total: round(incomeTotal - spendTotal),
    avg_monthly_spend: round(spendTotal / monthCount),
    categories,
    months,
    recurring,
    dormant_subscriptions: dormant,
    recurring_annual_total: round(recurring.reduce((s, r) => s + r.annualized, 0)),
    biggest_transactions: biggest,
    transactions: txns
  }
}];

const res = $input.first().json;

let raw = res.output ?? res.text ?? res.content ?? '';
if (typeof raw === 'object' && raw !== null) raw = JSON.stringify(raw);
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let a = null;
try { a = JSON.parse(raw); } catch (e) { a = null; }

const d = $('Build Insights Prompt').first().json.payload;
const cur = d.currency || '';
const fmt = (n) => cur + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// ---------- summary tiles ----------
const tiles = '<div class="tiles">'
  + '<div class="tile"><div class="tlabel">Total spent</div><div class="tval neg">' + esc(fmt(d.spend_total)) + '</div></div>'
  + '<div class="tile"><div class="tlabel">Total received</div><div class="tval pos">' + esc(fmt(d.income_total)) + '</div></div>'
  + '<div class="tile"><div class="tlabel">Net</div><div class="tval ' + (d.net_total >= 0 ? 'pos' : 'neg') + '">' + esc(fmt(d.net_total)) + '</div></div>'
  + '<div class="tile"><div class="tlabel">Avg monthly spend</div><div class="tval">' + esc(fmt(d.avg_monthly_spend)) + '</div></div>'
  + '</div>';

// ---------- category bars ----------
const maxCat = d.categories.length ? d.categories[0].total : 1;
const catRows = d.categories.map(c =>
  '<div class="crow">'
  + '<div class="cname">' + esc(c.category) + '<span class="ccount">' + c.count + ' txn</span></div>'
  + '<div class="cbarwrap"><div class="cbar" style="width:' + Math.max(1, (c.total / maxCat) * 100) + '%"></div></div>'
  + '<div class="camt">' + esc(fmt(c.total)) + '<span class="cpct">' + c.pct + '%</span></div>'
  + '<div class="cmerch">' + esc(c.top_merchants.map(m => m.name).join(', ')) + '</div>'
  + '</div>'
).join('');

// ---------- monthly table ----------
let monthTable = '';
if (d.months.length > 1) {
  monthTable = '<h2>Month by month</h2><div class="tablewrap"><table class="tbl"><thead><tr>'
    + '<th>Month</th><th class="r">Spent</th><th class="r">Received</th><th class="r">Net</th><th class="r">Transactions</th>'
    + '</tr></thead><tbody>'
    + d.months.map(m => '<tr><td>' + esc(m.month) + '</td>'
        + '<td class="r neg">' + esc(fmt(m.spend)) + '</td>'
        + '<td class="r pos">' + esc(fmt(m.income)) + '</td>'
        + '<td class="r ' + (m.net >= 0 ? 'pos' : 'neg') + '">' + esc(fmt(m.net)) + '</td>'
        + '<td class="r">' + m.count + '</td></tr>').join('')
    + '</tbody></table></div>';
}

// ---------- recurring ----------
let recSection = '';
if (d.recurring.length) {
  const dormantNames = {};
  d.dormant_subscriptions.forEach(x => { dormantNames[x.name] = true; });
  recSection = '<h2>Repeating charges</h2>'
    + '<div class="hint">Detected in code: same payee, near identical amount, similar day each month. Annualised means the typical charge multiplied by 12, not a figure taken from the statement.</div>'
    + '<div class="tablewrap"><table class="tbl"><thead><tr>'
    + '<th>Payee</th><th>Category</th><th class="r">Typical</th><th class="r">Charges</th><th>Last charged</th><th class="r">Annualised</th>'
    + '</tr></thead><tbody>'
    + d.recurring.map(r => '<tr' + (dormantNames[r.name] ? ' class="dormant"' : '') + '>'
        + '<td>' + esc(r.name) + (dormantNames[r.name] ? ' <span class="pill">stopped</span>' : '') + '</td>'
        + '<td>' + esc(r.category) + '</td>'
        + '<td class="r">' + esc(fmt(r.typical_amount)) + '</td>'
        + '<td class="r">' + r.charges + '</td>'
        + '<td>' + esc(r.last_seen) + '</td>'
        + '<td class="r">' + esc(fmt(r.annualized)) + '</td></tr>').join('')
    + '</tbody><tfoot><tr><td colspan="5"><b>Total if all continue for a year</b></td>'
    + '<td class="r"><b>' + esc(fmt(d.recurring_annual_total)) + '</b></td></tr></tfoot></table></div>';
}

// ---------- biggest ----------
const bigSection = '<h2>Largest transactions</h2><div class="tablewrap"><table class="tbl"><thead><tr>'
  + '<th>Date</th><th>Payee</th><th>Category</th><th class="r">Amount</th></tr></thead><tbody>'
  + d.biggest_transactions.map(t => '<tr><td>' + esc(t.date) + '</td><td>' + esc(t.name) + '</td>'
      + '<td>' + esc(t.category) + '</td><td class="r neg">' + esc(fmt(t.amount)) + '</td></tr>').join('')
  + '</tbody></table></div>';

// ---------- AI narrative ----------
let aiSection = '';
if (a) {
  const tagClass = (t) => t === 'Watch' ? 'hi' : (t === 'Positive' ? 'ok' : 'md');
  aiSection = '<h2>What the numbers say</h2>'
    + '<div class="verdict">' + esc(a.summary) + '</div>';

  if (Array.isArray(a.observations)) {
    aiSection += a.observations.map(o =>
      '<div class="obs"><div class="obshead">' + esc(o.title)
      + ' <span class="badge ' + tagClass(o.tag) + '">' + esc(o.tag) + '</span></div>'
      + '<div class="obsdetail">' + esc(o.detail) + '</div></div>'
    ).join('');
  }
  if (a.subscription_note) {
    aiSection += '<div class="obs"><div class="obshead">On the repeating charges</div>'
      + '<div class="obsdetail">' + esc(a.subscription_note) + '</div></div>';
  }
  if (Array.isArray(a.questions_to_check) && a.questions_to_check.length) {
    aiSection += '<h2>Worth checking yourself</h2><ul class="checks">'
      + a.questions_to_check.map(q => '<li>' + esc(q) + '</li>').join('') + '</ul>';
  }
} else {
  aiSection = '<h2>What the numbers say</h2><div class="warn">The written summary could not be generated this time, but every figure and table above was calculated directly from your statement and is unaffected.</div>';
}

// ---------- full transaction table + CSV export ----------
const txnRows = d.transactions.map(t =>
  '<tr data-cat="' + esc(t.category) + '"><td>' + esc(t.date) + '</td>'
  + '<td>' + esc(t.clean_name) + '<div class="rawdesc">' + esc(t.description) + '</div></td>'
  + '<td>' + esc(t.category) + '</td>'
  + '<td class="r ' + (t.amount < 0 ? 'neg' : 'pos') + '">' + esc(fmt(Math.abs(t.amount))) + '</td></tr>'
).join('');

const csvRows = [['Date', 'Payee', 'Description', 'Category', 'Amount']]
  .concat(d.transactions.map(t => [t.date, t.clean_name, t.description, t.category, t.amount]));
const csvText = csvRows.map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(',')).join('\n');
const csvB64 = Buffer.from(csvText, 'utf8').toString('base64');

const catOptions = ['<option value="">All categories</option>']
  .concat(d.categories.map(c => '<option value="' + esc(c.category) + '">' + esc(c.category) + '</option>')).join('');

const txnSection = '<h2>All transactions</h2>'
  + '<div class="controls"><select id="catfilter">' + catOptions + '</select>'
  + '<a class="dl" download="categorized-transactions.csv" href="data:text/csv;base64,' + csvB64 + '">Download CSV</a></div>'
  + '<div class="tablewrap"><table class="tbl" id="txntable"><thead><tr>'
  + '<th>Date</th><th>Payee</th><th>Category</th><th class="r">Amount</th></tr></thead><tbody>'
  + txnRows + '</tbody></table></div>';

const parseNote = '<div class="hint">Read ' + d.transaction_count + ' transactions from '
  + esc(d.period_start) + ' to ' + esc(d.period_end)
  + ' (' + esc(d.parse_mode === 'csv' ? 'CSV' : 'text') + ' mode, dates read as ' + esc(d.date_order || 'day/month/year') + ')'
  + (d.uncategorized_count ? '. ' + d.uncategorized_count + ' transaction(s) could not be categorised and were placed in Other.' : '')
  + '</div>';

const styles = '*{box-sizing:border-box}'
  + 'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f4f5f7;color:#1f2328;margin:0;padding:32px 16px;line-height:1.55}'
  + '.wrap{max-width:960px;margin:0 auto}'
  + 'h1{font-size:26px;margin:0 0 4px}h2{font-size:19px;margin:34px 0 12px;padding-bottom:6px;border-bottom:2px solid #d8dee4}'
  + '.hint{font-size:12.5px;color:#57606a;margin-bottom:12px}'
  + '.tiles{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0 8px}'
  + '.tile{flex:1;min-width:160px;background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:14px}'
  + '.tlabel{font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#57606a;margin-bottom:6px}'
  + '.tval{font-size:22px;font-weight:700}'
  + '.pos{color:#1a7f37}.neg{color:#cf222e}'
  + '.crow{display:grid;grid-template-columns:150px 1fr 120px;gap:10px;align-items:center;background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:10px 14px;margin-bottom:8px}'
  + '.cname{font-weight:600;font-size:14px}'
  + '.ccount{display:block;font-weight:400;font-size:11px;color:#57606a}'
  + '.cbarwrap{background:#eaeef2;border-radius:6px;height:14px;overflow:hidden}'
  + '.cbar{background:#1f2328;height:100%}'
  + '.camt{text-align:right;font-weight:600;font-size:14px}'
  + '.cpct{display:block;font-weight:400;font-size:11px;color:#57606a}'
  + '.cmerch{grid-column:1/-1;font-size:12px;color:#57606a}'
  + '.tablewrap{overflow-x:auto}'
  + '.tbl{width:100%;border-collapse:collapse;background:#fff;border:1px solid #d8dee4;border-radius:10px;overflow:hidden;font-size:13px}'
  + '.tbl th{background:#f6f8fa;text-align:left;padding:10px;border-bottom:1px solid #d8dee4;font-size:12px}'
  + '.tbl td{padding:9px 10px;border-bottom:1px solid #eaeef2;vertical-align:top}'
  + '.tbl tfoot td{background:#f6f8fa;border-top:1px solid #d8dee4}'
  + '.tbl .r{text-align:right}'
  + '.tbl tr.dormant{background:#fff8c5}'
  + '.pill{font-size:10px;background:#eac54f;color:#4d2d00;padding:1px 7px;border-radius:20px;vertical-align:middle}'
  + '.rawdesc{font-size:11px;color:#8c959f;margin-top:2px}'
  + '.verdict{background:#fff;border-left:4px solid #1f2328;border-radius:8px;padding:16px;font-size:15px;margin-bottom:14px}'
  + '.obs{background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:14px;margin-bottom:10px}'
  + '.obshead{font-weight:600;margin-bottom:5px}'
  + '.obsdetail{font-size:13.5px;color:#424a53}'
  + '.badge{display:inline-block;font-size:11px;padding:2px 9px;border-radius:20px;vertical-align:middle;margin-left:6px}'
  + '.badge.hi{background:#ffebe9;color:#cf222e}.badge.md{background:#ddf4ff;color:#0a3069}.badge.ok{background:#dafbe1;color:#1a7f37}'
  + '.checks{background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:14px 14px 14px 34px;font-size:14px}'
  + '.checks li{margin-bottom:7px}'
  + '.warn{background:#fff8c5;border:1px solid #eac54f;color:#9a6700;padding:12px 14px;border-radius:8px;font-size:13.5px}'
  + '.controls{display:flex;gap:10px;align-items:center;margin-bottom:10px;flex-wrap:wrap}'
  + '#catfilter{padding:7px 10px;border:1px solid #d8dee4;border-radius:8px;font-size:13px;background:#fff}'
  + '.dl{background:#1f2328;color:#fff;text-decoration:none;padding:8px 14px;border-radius:8px;font-size:13px}'
  + '.dl:hover{background:#444c56}'
  + '.foot{margin-top:28px;font-size:12px;color:#57606a;border-top:1px solid #d8dee4;padding-top:14px}';

const script = 'var f=document.getElementById("catfilter");'
  + 'if(f){f.addEventListener("change",function(){var v=f.value;'
  + 'document.querySelectorAll("#txntable tbody tr").forEach(function(r){'
  + 'r.style.display=(!v||r.getAttribute("data-cat")===v)?"":"none";});});}';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1">'
  + '<title>Expense Breakdown</title><style>' + styles + '</style></head><body><div class="wrap">'
  + '<h1>Expense breakdown</h1>'
  + parseNote
  + tiles
  + '<h2>Where the money went</h2>' + catRows
  + monthTable
  + recSection
  + bigSection
  + aiSection
  + txnSection
  + '<div class="foot">All totals, percentages and repeating charge detection were calculated arithmetically from your statement. '
  + 'Categories were assigned by an AI model from payee names and can be wrong, so check anything that looks off before relying on it. '
  + 'This is an informational summary of your own transactions, not financial advice.</div>'
  + '</div><script>' + script + '<\/script></body></html>';

return [{ json: { html } }];
